gv={'1':np.ones_like(v),'v':v,'v2':v**2,'v3':v**3,'v1.5':v**1.5,'sqrtv':np.sqrt(v),'1/v':1/v,'sinv':np.sin(v),'cosv':np.cos(v),'expv':np.exp(v),'expmv':np.exp(-v),'logv':np.log(v),'tanhv':np.tanh(v),'sin2v':np.sin(2*v),'cos2v':np.cos(2*v),'vlogv':v*np.log(v),'v2.5':v**2.5}
terms={a+'|'+b:fx[a]*gv[b] for a in fx for b in gv}
keys=list(terms); M=np.column_stack([terms[k] for k in keys])
