import numpy as np
from scipy.optimize import least_squares
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
fams={
 'cos(kv)': lambda p: np.cos(p[0]*v),
 'exp(kv)': lambda p: np.exp(p[0]*v),
 'sin(kv)': lambda p: np.sin(p[0]*v),
 'v^s': lambda p: v**p[0],
}
for name,g in fams.items():
    best=None
    rng=np.random.default_rng(2)
    for i in range(60):
        p0=[rng.normal()*1.5, rng.uniform(1.7,2.2), rng.normal(), rng.normal(), rng.uniform(0.2,2.5), rng.normal(), rng.uniform(-1,2)]
        def model(p):
            a,w,b,c,r_,d,k=p[0],p[1],p[2],p[3],p[4],p[5],p[6]
            return a*np.sin(w*np.sqrt(t))+b*t*np.log(t)*x**1.5+c*x**1.5+d*x**r_*g([k])
        try:
            r=least_squares(lambda p: model(p)-y, p0, max_nfev=1500)
            s=np.mean(r.fun**2)/np.var(y)
            if best is None or s<best[0]: best=(s,r.x)
        except Exception: pass
    print(name,best)
